<template><div class="page-container"><section class="page-hero"><div><h2>广告规则</h2><p>管理员广告豁免；管理菜单仍仅 OWNER 可操作。</p></div><GroupSelect v-model="group" @loaded="groups=$event"/></section><ElCard v-if="group" class="content-card"><ElForm label-position="top"><ElRow :gutter="20"><ElCol :xs="12" :sm="8"><ElFormItem label="广告拦截"><ElSwitch v-model="form.moderation"/></ElFormItem></ElCol><ElCol :xs="12" :sm="8"><ElFormItem label="链接拦截"><ElSwitch v-model="form.blockLinks"/></ElFormItem></ElCol><ElCol :xs="24" :sm="8"><ElFormItem label="处置方式"><ElSelect v-model="form.action"><ElOption label="删除并禁言" value="mute"/><ElOption label="仅删除" value="delete"/><ElOption label="删除并封禁" value="ban"/></ElSelect></ElFormItem></ElCol></ElRow><ElRow :gutter="20"><ElCol :xs="12"><ElFormItem label="扩展内置规则"><ElSwitch v-model="form.builtinRules"/></ElFormItem></ElCol><ElCol :xs="12"><ElFormItem label="群管理员广告豁免"><ElSwitch v-model="form.exemptAdmins"/></ElFormItem></ElCol></ElRow><ElFormItem label="拦截关键词（每行一条）"><ElInput v-model="keywords" type="textarea" :rows="5" placeholder="输入关键词"/></ElFormItem><ElRow :gutter="20"><ElCol :xs="24" :sm="8"><ElFormItem label="禁言时间（秒）"><ElInputNumber v-model="form.muteSeconds" :min="30" :max="86400"/></ElFormItem></ElCol><ElCol :xs="24" :sm="8"><ElFormItem label="重复消息触发次数"><ElInputNumber v-model="form.repeatLimit" :min="2" :max="50"/></ElFormItem></ElCol><ElCol :xs="24" :sm="8"><ElFormItem label="重复检测窗口（秒）"><ElInputNumber v-model="form.repeatSeconds" :min="1" :max="86400"/></ElFormItem></ElCol></ElRow><ElFormItem label="警告文案（支持 {name}、{group}、{rule}）"><ElInput v-model="form.warningText" type="textarea" :rows="2" maxlength="2000"/></ElFormItem><ElButton type="primary" @click="save">保存规则</ElButton></ElForm></ElCard><ElCard v-if="group" class="content-card" style="margin-top:18px"><template #header><div>分类广告规则 · {{catalog.length}} 类 · {{keywordCount}} 条内置词</div><small>电话邮箱、模糊营销与符号刷屏默认仅记录；其他类别跟随群处置。</small></template><ElTable :data="catalog"><ElTableColumn prop="name" label="规则" width="160"/><ElTableColumn label="启用" width="80"><template #default="{row}"><ElSwitch v-if="form.adRules?.[row.id]" v-model="form.adRules[row.id].enabled"/></template></ElTableColumn><ElTableColumn label="处置" width="170"><template #default="{row}"><ElSelect v-if="form.adRules?.[row.id]" v-model="form.adRules[row.id].action"><ElOption label="跟随群处置方式" value="inherit"/><ElOption label="仅记录" value="record"/><ElOption label="仅删除" value="delete"/><ElOption label="删除并禁言" value="mute"/><ElOption label="删除并封禁" value="ban"/></ElSelect></template></ElTableColumn><ElTableColumn prop="description" label="匹配内容" min-width="320"/></ElTable><ElButton type="primary" style="margin-top:16px" @click="save">保存规则</ElButton></ElCard><ElEmpty v-else description="请先接入群组"/></div></template>
<script setup lang="ts">
import GroupSelect from '@/components/guard/GroupSelect.vue'
import {saveSettings,getRuleCatalog,type Group} from '@/api/guard'
import {ElMessage} from 'element-plus'
const keywordCount=computed(()=>catalog.value.reduce((n,r)=>n+(r.count||0),0))
const group=ref(''),groups=ref<Group[]>([]),form=reactive<any>({}),keywords=ref(''),catalog=ref<any[]>([])
watch([group,groups,catalog],()=>{const s=groups.value.find(g=>g.id===group.value)?.settings;if(s){Object.assign(form,{moderation:s.moderation,blockLinks:s.blockLinks,action:s.action,builtinRules:s.builtinRules,exemptAdmins:s.exemptAdmins,muteSeconds:s.muteSeconds,repeatLimit:s.repeatLimit,repeatSeconds:s.repeatSeconds,warningText:s.warningText,adRules:Object.fromEntries(catalog.value.map(r=>[r.id,{enabled:s.adRules?.[r.id]?.enabled??true,action:s.adRules?.[r.id]?.action??r.action}]))});keywords.value=s.keywords.join('\n')}})
async function save(){await saveSettings(group.value,{...form,keywords:keywords.value.split('\n').map(x=>x.trim()).filter(Boolean)});ElMessage.success('已保存')}
onMounted(async()=>{catalog.value=await getRuleCatalog()})
</script>
